import{_ as l,o as r,c as i,a3 as e,j as t,a as d}from"./chunks/framework.BlfGB29P.js";const _=JSON.parse('{"title":"可访问性与移动端","description":"为 AI 聊天补齐可检查的无障碍与窄屏体验：键盘与焦点、读屏 live region、流式更新策略、触控目标与布局，避免空泛教条。","frontmatter":{"title":"可访问性与移动端","description":"为 AI 聊天补齐可检查的无障碍与窄屏体验：键盘与焦点、读屏 live region、流式更新策略、触控目标与布局，避免空泛教条。","outline":[2,3],"article":{"type":"concept","structure":"concept"}},"headers":[],"relativePath":"ts-ai/integration/ai-interaction/accessibility-mobile.md","filePath":"ts-ai/integration/ai-interaction/accessibility-mobile.md","lastUpdated":1786083160000}'),n={name:"ts-ai/integration/ai-interaction/accessibility-mobile.md"};function o(s,a,h,c,u,b){return r(),i("div",null,[...a[0]||(a[0]=[e(`<h1 id="可访问性与移动端" tabindex="-1">可访问性与移动端 <a class="header-anchor" href="#可访问性与移动端" aria-label="Permalink to &quot;可访问性与移动端&quot;">​</a></h1><blockquote><p>作者：cursor-grok-4.5</p></blockquote><p>AI 聊天不是静态表单：内容在涨、状态在变、还可能弹出工具确认。若只在桌面鼠标路径下「能用」，键盘用户会困在禁用的发送键上，读屏用户会被每个 <code>message.delta</code> 打断，手机用户会点不到停止按钮。</p><p>本篇给<strong>可检查</strong>的体验要求，不堆 WCAG 条文。状态机见 <a href="/ts-ai/integration/ai-interaction/streaming-state-feedback">流式状态与反馈</a>；确认卡片见 <a href="/ts-ai/integration/ai-interaction/tool-confirmation-human-loop">工具确认与人在回路</a>；Markdown 安全见 <a href="/ts-ai/integration/ai-interaction/markdown-code-citations">Markdown、代码与引用</a>。</p><h2 id="_1-定义与问题边界" tabindex="-1">1. 定义与问题边界 <a class="header-anchor" href="#_1-定义与问题边界" aria-label="Permalink to &quot;1. 定义与问题边界&quot;">​</a></h2><h3 id="_1-1-本篇覆盖" tabindex="-1">1.1 本篇覆盖 <a class="header-anchor" href="#_1-1-本篇覆盖" aria-label="Permalink to &quot;1.1 本篇覆盖&quot;">​</a></h3><table tabindex="0"><thead><tr><th>主题</th><th>目标</th></tr></thead><tbody><tr><td>键盘</td><td>不依赖鼠标完成发送、停止、确认、引用跳转</td></tr><tr><td>焦点</td><td>状态变化后焦点可预期，不丢到 <code>document.body</code></td></tr><tr><td>读屏</td><td>关键状态可感知，又不被流式洪水淹没</td></tr><tr><td>窄屏</td><td>单列可用；确认与输入不被遮挡</td></tr><tr><td>触控</td><td>主操作易于点按</td></tr></tbody></table><h3 id="_1-2-不覆盖" tabindex="-1">1.2 不覆盖 <a class="header-anchor" href="#_1-2-不覆盖" aria-label="Permalink to &quot;1.2 不覆盖&quot;">​</a></h3><ul><li>完整设计系统色板与对比度专题（只要求关键状态有非色差信号）。</li><li>具体 Vue/React 组件 API（实现分组负责）。</li><li>把所有 ARIA 角色背一遍。</li></ul><h2 id="_2-键盘与焦点" tabindex="-1">2. 键盘与焦点 <a class="header-anchor" href="#_2-键盘与焦点" aria-label="Permalink to &quot;2. 键盘与焦点&quot;">​</a></h2><h3 id="_2-1-必须可键盘完成的路径" tabindex="-1">2.1 必须可键盘完成的路径 <a class="header-anchor" href="#_2-1-必须可键盘完成的路径" aria-label="Permalink to &quot;2.1 必须可键盘完成的路径&quot;">​</a></h3><table tabindex="0"><thead><tr><th>路径</th><th>期望</th></tr></thead><tbody><tr><td>聚焦输入 → 发送</td><td><code>Enter</code> 发送（Shift+Enter 换行，若多行）；或 Tab 到发送按钮激活</td></tr><tr><td>流式中停止</td><td>Tab 到「停止」或快捷键（需可见提示）</td></tr><tr><td>工具确认</td><td>Tab 在卡片内循环；批准/拒绝可激活</td></tr><tr><td>引用芯片</td><td>可聚焦、可激活，打开来源</td></tr><tr><td>Thread 列表</td><td>方向键或 Tab 移动；Enter 打开</td></tr></tbody></table><h3 id="_2-2-焦点规则" tabindex="-1">2.2 焦点规则 <a class="header-anchor" href="#_2-2-焦点规则" aria-label="Permalink to &quot;2.2 焦点规则&quot;">​</a></h3><table tabindex="0"><thead><tr><th>时机</th><th>焦点去向</th></tr></thead><tbody><tr><td>进入 <code>tool_pending</code></td><td>确认卡片容器或首个可编辑字段</td></tr><tr><td>确认提交成功回到 <code>streaming</code></td><td>不宜强制抢焦点到输入；可读屏宣告即可</td></tr><tr><td><code>run.completed</code> / <code>failed</code></td><td>失败时焦点可移到错误区域或「重试」</td></tr><tr><td>打开来源面板</td><td>面板内首个来源项；关闭后回到触发芯片</td></tr></tbody></table><h3 id="_2-3-禁用不等于消失" tabindex="-1">2.3 禁用不等于消失 <a class="header-anchor" href="#_2-3-禁用不等于消失" aria-label="Permalink to &quot;2.3 禁用不等于消失&quot;">​</a></h3><p>发送按钮在 <code>streaming</code> 禁用时：</p><ul><li>仍应留在 Tab 序中<strong>或</strong>提供等价的「停止」在同一区域。</li><li>用 <code>aria-disabled</code> / 原生 <code>disabled</code> 时，确保读屏能听到不可用原因（可通过邻近 live region 补充「正在生成，发送已暂停」）。</li></ul><h3 id="_2-4-焦点陷阱" tabindex="-1">2.4 焦点陷阱 <a class="header-anchor" href="#_2-4-焦点陷阱" aria-label="Permalink to &quot;2.4 焦点陷阱&quot;">​</a></h3><p>确认模态若使用模态层：焦点锁在卡片内，<code>Esc</code> 映射为「拒绝」或「关闭说明」（产品二选一，需明示）。非模态内嵌卡片：不陷阱，但初始聚焦到卡片。</p><h2 id="_3-读屏与流式-live-region" tabindex="-1">3. 读屏与流式 live region <a class="header-anchor" href="#_3-读屏与流式-live-region" aria-label="Permalink to &quot;3. 读屏与流式 live region&quot;">​</a></h2><h3 id="_3-1-为什么不能每-delta-都读" tabindex="-1">3.1 为什么不能每 delta 都读 <a class="header-anchor" href="#_3-1-为什么不能每-delta-都读" aria-label="Permalink to &quot;3.1 为什么不能每 delta 都读&quot;">​</a></h3><p><code>message.delta</code> 可能每秒数十次。若整个助手气泡放在 <code>aria-live=&quot;assertive&quot;</code>，读屏会不断打断，任务不可用。</p><h3 id="_3-2-推荐分区" tabindex="-1">3.2 推荐分区 <a class="header-anchor" href="#_3-2-推荐分区" aria-label="Permalink to &quot;3.2 推荐分区&quot;">​</a></h3><table tabindex="0"><thead><tr><th>区域</th><th>技术意向</th><th>读什么</th></tr></thead><tbody><tr><td>助手正文容器</td><td>普通文档流，<strong>不要</strong>对每个 delta polite 广播全文</td><td>用户主动浏览时再读</td></tr><tr><td>状态 live region</td><td><code>aria-live=&quot;polite&quot;</code> 的<strong>短文本</strong>节点</td><td>「正在生成」「需要确认」「已完成」「失败：…」「已取消」</td></tr><tr><td>确认卡片</td><td>标题与风险句可被聚焦读取；出现时状态区宣告一次</td><td>「需要你确认：发送退款」</td></tr><tr><td>错误</td><td><code>polite</code> 或在失败时 <code>assertive</code>（慎用）</td><td>失败原因摘要</td></tr></tbody></table><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[visually optional] &lt;div aria-live=&quot;polite&quot; aria-atomic=&quot;true&quot;&gt;</span></span>
<span class="line"><span>  正在生成回答</span></span>
<span class="line"><span>&lt;/div&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>状态变化时更新<strong>一句</strong>话，而不是粘贴累计 Markdown。</p><h3 id="_3-3-状态-→-宣告文案" tabindex="-1">3.3 状态 → 宣告文案 <a class="header-anchor" href="#_3-3-状态-→-宣告文案" aria-label="Permalink to &quot;3.3 状态 → 宣告文案&quot;">​</a></h3>`,27),t("table",{tabindex:"0"},[t("thead",null,[t("tr",null,[t("th",null,"状态 / 事件"),t("th",null,"宣告示例")])]),t("tbody",null,[t("tr",null,[t("td",null,[t("code",null,"submitting")]),t("td",null,"正在发送")]),t("tr",null,[t("td",null,[t("code",null,"run.started"),d(" / "),t("code",null,"streaming")]),t("td",null,"正在生成回答")]),t("tr",null,[t("td",null,[t("code",null,"tool.confirmation_required")]),t("td",null,"需要你确认工具操作")]),t("tr",null,[t("td",null,[t("code",null,"run.completed")]),t("td",null,"回答已完成")]),t("tr",null,[t("td",null,[t("code",null,"run.failed")]),t("td",{短因:""},"回答失败：")]),t("tr",null,[t("td",null,[t("code",null,"run.cancelled")]),t("td",null,"已取消生成")]),t("tr",null,[t("td",null,[t("code",null,"citation.added"),d("（可选，节流）")]),t("td",{标题:""},"新增来源：")]),t("tr",null,[t("td",null,[t("code",null,"file.index.updated")]),t("td",{状态:""},"文件「{名}」索引")])])],-1),e(`<h3 id="_3-4-长任务回访" tabindex="-1">3.4 长任务回访 <a class="header-anchor" href="#_3-4-长任务回访" aria-label="Permalink to &quot;3.4 长任务回访&quot;">​</a></h3><p>回访 hydrate 时宣告一次当前 Run 状态即可（「该对话有任务进行中」），不要重放历史所有事件。见 <a href="/ts-ai/integration/ai-interaction/long-running-task-experience">长任务体验</a>。</p><h3 id="_3-5-消息列表的读屏结构" tabindex="-1">3.5 消息列表的读屏结构 <a class="header-anchor" href="#_3-5-消息列表的读屏结构" aria-label="Permalink to &quot;3.5 消息列表的读屏结构&quot;">​</a></h3><p>时间线建议：</p><table tabindex="0"><thead><tr><th>元素</th><th>建议</th></tr></thead><tbody><tr><td>每条 Message</td><td>可用分组或 <code>article</code>/<code>listitem</code> 语义；标明「你」/「助手」</td></tr><tr><td>工具卡片</td><td>独立可聚焦区域，标题含工具产品名与状态</td></tr><tr><td>引用列表</td><td>来源面板用列表；项内含标题与「打开」控件名</td></tr><tr><td>装饰性脉冲动画</td><td><code>aria-hidden=&quot;true&quot;</code>，状态靠 live region</td></tr></tbody></table><p>避免把整条 Thread 包成一个巨大 live region。</p><h2 id="_4-窄屏布局" tabindex="-1">4. 窄屏布局 <a class="header-anchor" href="#_4-窄屏布局" aria-label="Permalink to &quot;4. 窄屏布局&quot;">​</a></h2><h3 id="_4-1-单列结构" tabindex="-1">4.1 单列结构 <a class="header-anchor" href="#_4-1-单列结构" aria-label="Permalink to &quot;4.1 单列结构&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────┐</span></span>
<span class="line"><span>│ Thread 标题 / 返回   │</span></span>
<span class="line"><span>├─────────────────────┤</span></span>
<span class="line"><span>│ 消息时间线（可滚）   │</span></span>
<span class="line"><span>│ …                    │</span></span>
<span class="line"><span>├─────────────────────┤</span></span>
<span class="line"><span>│ 确认卡片（若 pending）│</span></span>
<span class="line"><span>├─────────────────────┤</span></span>
<span class="line"><span>│ 输入 + 发送/停止     │</span></span>
<span class="line"><span>└─────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><table tabindex="0"><thead><tr><th>规则</th><th>说明</th></tr></thead><tbody><tr><td>列表与详情</td><td>小屏用栈式路由：先列表后详情，避免永久双栏挤爆</td></tr><tr><td>确认卡片</td><td>优先内嵌在输入上方；避免超大居中模态挡住上下文</td></tr><tr><td>代码块</td><td>横向滚动，不强迫整页变宽</td></tr><tr><td>来源面板</td><td>底栏抽屉或新页，而不是桌面式右侧栏硬挤</td></tr></tbody></table><h3 id="_4-2-视觉与安全区" tabindex="-1">4.2 视觉与安全区 <a class="header-anchor" href="#_4-2-视觉与安全区" aria-label="Permalink to &quot;4.2 视觉与安全区&quot;">​</a></h3><ul><li>底部输入避开设备 Home 指示条（安全区 padding）。</li><li>键盘弹起时，保证输入与发送仍可见（滚动/resize 处理由实现分组完成，本篇要求验收）。</li><li>状态条与错误不长期遮挡最后一条消息的阅读。</li></ul><h3 id="_4-3-横屏" tabindex="-1">4.3 横屏 <a class="header-anchor" href="#_4-3-横屏" aria-label="Permalink to &quot;4.3 横屏&quot;">​</a></h3><p>不强制单独设计；至少：输入区不消失、确认按钮可点。</p><h3 id="_4-4-thread-切换与返回" tabindex="-1">4.4 Thread 切换与返回 <a class="header-anchor" href="#_4-4-thread-切换与返回" aria-label="Permalink to &quot;4.4 Thread 切换与返回&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>窄屏期望</th></tr></thead><tbody><tr><td>列表 → 详情</td><td>系统返回或页内返回均回到列表，且保留滚动位置更佳</td></tr><tr><td>详情内打开来源抽屉</td><td>关闭抽屉仍在同一 Thread，不误退到列表</td></tr><tr><td>有 <code>tool_pending</code></td><td>返回列表前保留徽标「待确认」，再进详情仍见卡片</td></tr></tbody></table><h2 id="_5-触控目标与手势" tabindex="-1">5. 触控目标与手势 <a class="header-anchor" href="#_5-触控目标与手势" aria-label="Permalink to &quot;5. 触控目标与手势&quot;">​</a></h2><h3 id="_5-1-目标尺寸" tabindex="-1">5.1 目标尺寸 <a class="header-anchor" href="#_5-1-目标尺寸" aria-label="Permalink to &quot;5.1 目标尺寸&quot;">​</a></h3><table tabindex="0"><thead><tr><th>控件</th><th>建议</th></tr></thead><tbody><tr><td>发送 / 停止 / 批准 / 拒绝</td><td>易点区域边长约 ≥ 44px（或等效 padding）</td></tr><tr><td>引用芯片</td><td>过小时扩大点击热区，不缩小字到不可读</td></tr><tr><td>列表行</td><td>整行可点，不只点文字</td></tr></tbody></table><h3 id="_5-2-手势边界" tabindex="-1">5.2 手势边界 <a class="header-anchor" href="#_5-2-手势边界" aria-label="Permalink to &quot;5.2 手势边界&quot;">​</a></h3><table tabindex="0"><thead><tr><th>手势</th><th>建议</th></tr></thead><tbody><tr><td>下滑刷新</td><td>勿与消息滚动冲突；或仅在列表顶触发</td></tr><tr><td>左滑删除 Thread</td><td>需有明确按钮替代路径（键盘/读屏不可靠依赖滑动）</td></tr><tr><td>双击点赞等</td><td>非核心；核心路径必须有按钮</td></tr></tbody></table><h3 id="_5-3-误触" tabindex="-1">5.3 误触 <a class="header-anchor" href="#_5-3-误触" aria-label="Permalink to &quot;5.3 误触&quot;">​</a></h3><p>流式中「停止」与「发送」不要换位过快导致误触；<code>tool_pending</code> 时批准按钮不要与拒绝过近无间距。高风险批准可要求二次确认（产品策略）。</p><h2 id="_6-与-ai-特有组件的交集" tabindex="-1">6. 与 AI 特有组件的交集 <a class="header-anchor" href="#_6-与-ai-特有组件的交集" aria-label="Permalink to &quot;6. 与 AI 特有组件的交集&quot;">​</a></h2><h3 id="_6-1-markdown-与代码" tabindex="-1">6.1 Markdown 与代码 <a class="header-anchor" href="#_6-1-markdown-与代码" aria-label="Permalink to &quot;6.1 Markdown 与代码&quot;">​</a></h3><ul><li>代码复制按钮可键盘激活，并有「已复制」宣告。</li><li>链接可聚焦；拒绝 <code>javascript:</code> 等危险协议（见 Markdown 篇）。</li><li>不要用仅靠颜色的「引用高亮」；配合下划线/图标。</li></ul><h3 id="_6-2-工具确认" tabindex="-1">6.2 工具确认 <a class="header-anchor" href="#_6-2-工具确认" aria-label="Permalink to &quot;6.2 工具确认&quot;">​</a></h3><ul><li>风险级别除颜色外加文字「高风险」。</li><li>错误参数用 <code>aria-describedby</code> 关联字段错误。</li><li>提交中按钮禁用并宣告「正在提交确认」。</li></ul><h3 id="_6-3-附件与索引" tabindex="-1">6.3 附件与索引 <a class="header-anchor" href="#_6-3-附件与索引" aria-label="Permalink to &quot;6.3 附件与索引&quot;">​</a></h3><p><code>file.index.updated</code> 变化时，附件芯片文本更新为「索引中 / 就绪 / 失败」，并在状态 live region 节流宣告，避免文件很多时刷屏。</p><h2 id="_7-可检查清单" tabindex="-1">7. 可检查清单 <a class="header-anchor" href="#_7-可检查清单" aria-label="Permalink to &quot;7. 可检查清单&quot;">​</a></h2><h3 id="_7-1-键盘" tabindex="-1">7.1 键盘 <a class="header-anchor" href="#_7-1-键盘" aria-label="Permalink to &quot;7.1 键盘&quot;">​</a></h3><ul><li>[ ] 仅用键盘可发送消息、停止生成、完成一次工具确认。</li><li>[ ] 引用芯片可聚焦并打开来源，关闭后焦点回到芯片。</li><li>[ ] 无意外焦点丢失到空白页；模态确认有 Esc 行为说明。</li></ul><h3 id="_7-2-读屏" tabindex="-1">7.2 读屏 <a class="header-anchor" href="#_7-2-读屏" aria-label="Permalink to &quot;7.2 读屏&quot;">​</a></h3><ul><li>[ ] 存在独立状态 live region；内容是短状态句，不是全文 Markdown。</li><li>[ ] <code>tool.confirmation_required</code>、终态事件会宣告一次。</li><li>[ ] 连续 <code>message.delta</code> 不会导致持续打断朗读。</li></ul><h3 id="_7-3-移动与触控" tabindex="-1">7.3 移动与触控 <a class="header-anchor" href="#_7-3-移动与触控" aria-label="Permalink to &quot;7.3 移动与触控&quot;">​</a></h3><ul><li>[ ] 窄屏单列可完成同上主路径。</li><li>[ ] 主按钮触控热区足够；安全区未遮挡输入。</li><li>[ ] 虚拟键盘弹出后仍能看到输入与主按钮。</li></ul><h3 id="_7-4-状态诚实-与无障碍叠加" tabindex="-1">7.4 状态诚实（与无障碍叠加） <a class="header-anchor" href="#_7-4-状态诚实-与无障碍叠加" aria-label="Permalink to &quot;7.4 状态诚实（与无障碍叠加）&quot;">​</a></h3><ul><li>[ ] 读屏宣告的状态与 UI 状态机一致（无假完成）。</li><li>[ ] 失败/取消有文本，不只靠红色图标。</li></ul><h2 id="_8-常见误区与总结" tabindex="-1">8. 常见误区与总结 <a class="header-anchor" href="#_8-常见误区与总结" aria-label="Permalink to &quot;8. 常见误区与总结&quot;">​</a></h2><h3 id="_8-1-常见误区" tabindex="-1">8.1 常见误区 <a class="header-anchor" href="#_8-1-常见误区" aria-label="Permalink to &quot;8.1 常见误区&quot;">​</a></h3><table tabindex="0"><thead><tr><th>误区</th><th>纠正</th></tr></thead><tbody><tr><td>给气泡加 <code>aria-live=&quot;assertive&quot;</code> 跟读全文</td><td>改为短状态 region</td></tr><tr><td>「移动端以后再说」</td><td>确认与停止在窄屏更易误触，更要先测</td></tr><tr><td>只测 VoiceOver 或只测 TalkBack</td><td>至少键盘 + 一种读屏 + 一种窄屏</td></tr><tr><td>对比度靠品牌色硬扛</td><td>状态另加文字/图标</td></tr><tr><td>用 placeholder 代替标签</td><td>输入区仍需可见标签或 <code>aria-label</code>（如「消息」）</td></tr><tr><td>停止按钮只放图标</td><td>提供可访问名称「停止生成」</td></tr></tbody></table><h3 id="_8-2-最小手工测试脚本" tabindex="-1">8.2 最小手工测试脚本 <a class="header-anchor" href="#_8-2-最小手工测试脚本" aria-label="Permalink to &quot;8.2 最小手工测试脚本&quot;">​</a></h3><ol><li>拔掉鼠标：完成发送 → 停止 →（若有）确认批准。</li><li>开读屏：听状态句是否与屏幕一致；确认 delta 未刷屏。</li><li>视口缩到 ~375px：完成同上路径；虚拟键盘下输入仍可见。</li><li>人为制造 <code>run.failed</code>：错误可被读到且可聚焦到重试。</li></ol><h3 id="_8-3-总结" tabindex="-1">8.3 总结 <a class="header-anchor" href="#_8-3-总结" aria-label="Permalink to &quot;8.3 总结&quot;">​</a></h3><p>可访问性在 AI 聊天里的关键点是：<strong>键盘能走完主路径、焦点跟得上确认与错误、读屏听状态而不是听洪水 delta、窄屏单列可操作。</strong> 把第 7 节清单当作验收门禁；具体组件实现放到 vue-nuxt / react-next，本篇原则两边共用。</p>`,46)])])}const m=l(n,[["render",o]]);export{_ as __pageData,m as default};
